-- supabase/scholarship_enrichment_batch16_2026-10-27.sql
-- Enrichment Batch 16 (2026-10-27), France: the programme-level PSL Graduate Programs
-- excellence grants that constituted the retired umbrella record 52 (pass 109), verified
-- first-hand on the official PSL/Dauphine-PSL pages the same day:
--   961 PSL Graduate Program in Computer Science Excellence Grants     (rel 10)
--   962 PSL Graduate Program in Finance Excellence Scholarships        (rel 9)
--   963 PSL Graduate Program in Mathematics and Applications Exc.      (rel 10)
-- sources 3098 (pginfo CS) / 3099 (Dauphine M1 Finance) / 3097 (2026 mathematics flyer);
-- links 961->3098, 962->3099, 963->3097; university_scholarships 695/694/693 (university 44).
-- Effect (verified 2026-10-27): active 540 (was 537), retired 171, active rel-4 42,
-- future deadlines 183. Replay: timestamps use now(); run against the post-pass-109 state.

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (961, 'PSL Graduate Program in Computer Science Excellence Grants', 'Université PSL - Graduate Program in Computer Science', 'France', 'Partial Funding', 0, 'Annual spring call alongside the master''s application: the last published round closed on 8 June 2026 (jury in June 2026) for September 2026 entry. Apply via the MyCandidature platform - tick the grant checkbox and add a short motivation letter (M2 IASD/MODO), via the dedicated "Computer Science Graduate Program - scholarship of excellence" campaign on MyCandidature if applying to M1 I2D through MonMaster, or by email to the Graduate Programme director for M2 MPRI.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["PSL Master's in Computer Science, research-oriented tracks only: M1 I2D (Informatique pour la décision, Dauphine-PSL); M2 IASD (Artificial Intelligence, Systems and Data - initial-training version only); M2 MODO (Modelling, Optimisation, Decision and Organisation); M2 MPRI (Algorithms and Foundations of Programming - only for students who completed their M1 at PSL)"]$j$, '[]', NULL, NULL, false, true, $desc$The Computer Science Graduate Program of Université PSL offers excellence grants to students applying to its research-oriented master's programmes: selected applicants receive a scholarship of €1,200 per month for ten months (September to June), with university registration fees remaining payable out of the grant. The scheme is based on academic excellence and is open to students of all nationalities holding a Bachelor's degree (for entry into Master 1) or a validated Master 1 year (for entry into Master 2), or equivalents - but awards are made only to applicants registered in one of the programme's research-oriented tracks: the M1 I2D (computer science for decision-making) at Université Paris Dauphine-PSL, the M2 IASD (Artificial Intelligence, Systems and Data) in its regular, non-apprenticeship version, the M2 MODO (Modelling, Optimisation, Decision and Organisation), or the M2 MPRI (Algorithms and Foundations of Programming) for students who completed their M1 at PSL. Applications ride on the master's application itself: for M2 IASD and MODO, candidates tick the corresponding checkbox in the MyCandidature application and add a short motivation letter as supplementary material; M1 I2D applicants who go through the national MonMaster platform file a second MyCandidature application to the dedicated "Computer Science Graduate Program - scholarship of excellence" campaign; M2 MPRI candidates email their motivation letter to the Graduate Programme director. The grant cannot be combined with other funding (except joint programmes with French embassies or French institutes abroad), attendance is required (interruption can terminate payments), and AI-focused M2 IASD students may additionally compete for the parallel PR[AI]RIE institute grants described on the same page. The last published call closed on 8 June 2026 with a June 2026 jury, so the next round is expected in spring 2027 for September 2027 entry.$desc$, $req$Applicants must hold a Bachelor's degree (for M1 entry) or a validated Master 1 year (for M2 entry), or an equivalent, and be applying to or registered in one of the eligible research-oriented tracks (M1 I2D; M2 IASD regular version; M2 MODO; M2 MPRI restricted to PSL M1 graduates). Selection is on academic excellence as shown in the master's application file, supported by a short motivation letter explaining why the candidate deserves the grant and how it will allow them to study in good conditions. All nationalities are eligible; note the platform routing - most EU students and internationals without Études en France access apply to M1 I2D through MonMaster and must then file a separate MyCandidature grant application, while MyCandidature applicants simply tick the grant box. The grant is incompatible with other funding except joint programmes with French embassies/French institutes abroad, and registration fees are payable by the student out of the €1,200 monthly allowance. No numeric GPA or IELTS threshold is published for the grant (admission to each track follows the master's own rules), so min_gpa/min_ielts are not recorded.$req$, 'https://pginfo.ens.psl.eu/last/scholarship_grants_en.html', 'https://pginfo.ens.psl.eu/last/scholarship_grants_en.html', 'https://candidatures.dauphine.fr/mycandidature/front/', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 16) from the PSL Graduate Program in Computer Science's official scholarship-grants page (pginfo.ens.psl.eu) fetched the same day (monthly scholarship of €1,200 for 10 months, September to June, registration fees payable out of the grant; academic excellence, all nationalities; Bachelor's for M1 / validated M1 for M2; eligible research-oriented tracks M1 I2D, M2 IASD initial training, M2 MODO, M2 MPRI restricted to PSL M1 graduates; application via the MyCandidature checkbox plus motivation letter, a separate MyCandidature "scholarship of excellence" campaign for MonMaster applicants, or email to the programme director for MPRI; non-cumulation except French embassy/institute joint programmes; attendance condition; PR[AI]RIE parallel grants for M2 IASD; deadline 8 June 2026 with a June 2026 jury for the September 2026 intake). Award stored as 1200 EUR/month/fixed (€12,000 over the ten-month disbursement). deadline_date is NULL with type 'not_published' because the fetched page still shows the closed 8 June 2026 round; the annual spring pattern (June deadline and jury for September entry) is recorded in rounds and expected_deadline_period, with status 'upcoming'. This record documents, on its own programme-level terms, one of the constituent grants of the umbrella record 52 ("PSL Excellence Scholarship") retired in cleanup pass 109. min_gpa/min_ielts NULL. university_id set to the existing Université PSL record (44) and a university_scholarships row added.$note$, 44, 1200, 'EUR', 'month', 'fixed', NULL, 'Scholarship of €1,200/month for 10 months (September-June; €12,000 per academic year), awarded on academic excellence; registration fees are payable out of the grant', 'Registration fees are not waived - they remain payable by the student out of the monthly allowance.', 'The grant scheme publishes no IELTS figure; language requirements follow the admission rules of each master''s track.', $j$["Bachelor's degree (M1 entry) or validated Master 1 year (M2 entry), or equivalent, with transcripts showing academic excellence", "Short motivation letter explaining why the candidate deserves the grant (uploaded as supplementary material in MyCandidature; by email to the Graduate Programme director for M2 MPRI)", "Master's application to an eligible track (MyCandidature checkbox ticked; MonMaster applicants to M1 I2D file the separate MyCandidature 'scholarship of excellence' campaign)"]$j$, NULL, 'June', $json$[{"intake": "2026-2027 (last published)", "deadline": "2026-06-08", "jury": "2026-06", "status": "closed"}, {"pattern": "Annual: applications ride on the master's application in spring, with an early-June deadline (8 June 2026 in the last published call) and a June jury for September entry; expect the next round in spring 2027"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (962, 'PSL Graduate Program in Finance Excellence Scholarships (Dauphine-PSL)', 'Université Paris Dauphine-PSL - Graduate Program in Finance', 'France', 'Partial Funding', 0, 'No separate application and no published deadline: these excellence scholarships are awarded each year by the Graduate Program in Finance on academic merit - at M1 on entry/profile for Research in Finance students and to the top M1 performer across the six fundamental courses (first exam session), and at M2 to the top students of the PhD Qualifying Year and of the M2 104.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["Dauphine-PSL Master's in Finance: M1 Finance - Research in Finance major; M2 Research in Finance - 104 (including the PhD Qualifying Year track)"]$j$, '[]', NULL, NULL, false, true, $desc$The Graduate Program in Finance at Université Paris Dauphine-PSL awards excellence scholarships of €12,000 per year (paid as €6,000 per semester) to students with outstanding academic achievements in the Research in Finance track of its master's in Finance. In the first year (M1 Finance - Research in Finance major) the scholarships reward students with excellent grades, including an award for the M1 student obtaining the highest grades in the six fundamental courses of the M1 curriculum at the first exam session; winners of the M1-year award may have it extended for one further year, subject to conditions and commission approval, if they enrol in the second year of the Research in Finance master's. In the second year (M2 Research in Finance - 104), two scholarships of €6,000 per semester are potentially available: one for the top student of the PhD Qualifying Year track (subject to sufficient grades - and the student must commit to continuing into the Finance PhD Program of Université Paris Dauphine-PSL) and one for the top student of the M2 104; no application is required for these. Awards are made on student merit as well as on funds available to the Graduate Program, are paid in two instalments conditional on enrolment and on passing the first semester (M1) or third semester (M2), and do not cover tuition fees, which remain payable by the student. The scheme is listed by Dauphine-PSL among its scholarships for French and international students enrolled in these finance programmes - it is a small, grades-based merit prize internal to the Research in Finance track rather than an open application-based scholarship, and it is catalogued on those honest terms.$desc$, $req$Eligible students are French and international students enrolled in the Research in Finance track (M1 Finance - Research in Finance major, or M2 Research in Finance - 104, including its PhD Qualifying Year). There is no application form: awards are decided on academic excellence - excellent grades at M1 level (including the best aggregate in the six fundamental M1 courses at the first exam session) and, at M2, the top-ranked students of the PhD Qualifying Year and of the M2 104; the PhD Qualifying Year awardee must commit to continuing into Dauphine-PSL's Finance PhD Program. The second instalment requires passing the preceding semester, M1 awards extend into M2 only with commission approval, and all awards depend on funds available to the Graduate Program. Tuition fees are not covered. No GPA figure in a convertible scale and no IELTS threshold are published for these internal merit awards, so min_gpa/min_ielts are not recorded; admission to the master's itself follows Dauphine-PSL rules.$req$, 'https://dauphine.psl.eu/en/training/masters-degrees/finance/finance-masters-year-1/excellence-scholarship', 'https://dauphine.psl.eu/en/training/masters-degrees/finance/finance-masters-year-1/excellence-scholarship', 'https://dauphine.psl.eu/en/training/masters-degrees/finance/finance-masters-year-1/excellence-scholarship', 'annual', 'upcoming', 'verified', 9, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 16) from Université Paris Dauphine-PSL's official programme pages fetched the same day - the M1 Finance "Excellence Scholarship" page (scholarships of €12,000 per year or €6,000 per semester awarded by the Graduate Program of Finance; eligible: M1 students in the Research in Finance track with excellent grades and the M1 student with the highest grades in the six fundamental courses at the first exam session; awarded on merit and on funds available) and the M2 Research in Finance - 104 "Excellence scholarship" page (two potential scholarships of €6,000 per semester: top of the PhD Qualifying Year, who must commit to the Dauphine-PSL Finance PhD Program, and top of the M2 104; no application required; second scholarship subject to sufficient funds) - corroborated by Dauphine-PSL's central "Scholarships and Social Assistance" listing (excellence scholarship fixed at €12,000/year; French and international students in the M1 Research in Finance / M2 104 programmes; M1 award extendable one year into the M2 with commission approval; paid in two instalments after enrolment and after passing the preceding semester; tuition not covered). Award stored as NULL (EUR, 'year', 'variable'): annual value depends on semester-by-semester activation and the programme's available funds. Reliability 9 rather than 10 because sanctioned numbers of awards and their activation are funds-contingent and the scheme is an internal top-grades merit prize rather than an open application-based scholarship - stated plainly in the description. deadline_date NULL/'not_published' (no application exists); status 'upcoming' as an annually awarded scheme. This record documents, on its own programme-level terms, one of the constituent grants of the umbrella record 52 retired in cleanup pass 109. min_gpa/min_ielts NULL. university_id set to the existing Université PSL record (44; Dauphine-PSL is a PSL component school) and a university_scholarships row added.$note$, 44, NULL, 'EUR', 'year', 'variable', NULL, 'Excellence scholarships of €12,000/year (€6,000/semester) for outstanding students in the Research in Finance track, awarded on grades/merit subject to programme funds; M1 awards may extend into M2; two €6,000/semester top-student awards in the M2 104. Tuition not covered.', 'Tuition fees are not covered and remain payable by the student.', 'No IELTS threshold is published for these internal merit awards; language requirements follow Dauphine-PSL master''s admission rules.', $j$["Enrolment/admission in the eligible Dauphine-PSL finance programmes (M1 Finance - Research in Finance major; M2 Research in Finance - 104)", "No separate scholarship application - awards are made on academic record and first-session grades (M2 top-student awards expressly require no application)", "For the PhD Qualifying Year award: commitment to continue into the Finance PhD Program of Université Paris Dauphine-PSL"]$j$, NULL, NULL, $json$[{"pattern": "Annual internal merit awards tied to the academic year: decided on entry profile and first-examination-session grades within the Research in Finance track, with the second instalment conditional on passing the preceding semester; no application window or deadline is published"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (963, 'PSL Graduate Program in Mathematics and Applications Excellence Scholarships', 'Université PSL - Graduate Program in Mathematics and Applications', 'France', 'Partial Funding', 0, 'Annual spring call via the PSL MyCandidature platform (search for "Graduate Program in Mathematics and Applications"): the last published call ran from 27 February to 25 May 2026 for 2026-2027 entry (M1 Applied Mathematics - Advanced Mathematics major and the MAPPA double degree closed earlier, on 11 May 2026). Expect the next round in spring 2027.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["PSL Master in Mathematics curricula: M1 Applied Mathematics - Advanced Mathematics major; M1 Pure Mathematics; M2 Applied and Theoretical Mathematics (MATH); M2 Artificial Intelligence, Systems and Data - Mathematics track (IASD-Mathematics); M2 Mathematics for Insurance, Economics and Finance (MASEF); plus the MAPPA French-Italian double degree with the University of Padova (M1 in Padova, M2 in Paris)"]$j$, '[]', NULL, NULL, false, true, $desc$The Graduate Program in Mathematics and Applications of Université PSL offers master's scholarships to national and international students of academic excellence: a ten-month allowance of €1,200 per month for one year, renewable for a second year subject to conditions and a renewal application. The grants attach to the research-oriented curricula of the PSL Master in Mathematics - the M1 in Applied Mathematics (Advanced Mathematics major), the M1 in Pure Mathematics, the M2 Applied and Theoretical Mathematics (MATH), the M2 Artificial Intelligence, Systems and Data - Mathematics track (IASD-Mathematics) and the M2 Mathematics for Insurance, Economics and Finance (MASEF) - taught with the mathematics laboratories CEREMADE (Université Paris Dauphine-PSL) and DMA (École Normale Supérieure-PSL); the MAPPA French-Italian double degree with the University of Padova (M1 in Padova, M2 in Paris) is covered on the same schedule as the M1 Applied Mathematics applications. Teaching is in English except for the first year of the Pure Mathematics curriculum. Selection is through an online application on academic-excellence criteria, filed on the PSL MyCandidature platform under "Graduate Program in Mathematics and Applications"; the 2026-2027 call ran from 27 February 2026 to 25 May 2026 (11 May 2026 for the M1 Applied Mathematics - Advanced Mathematics major and MAPPA), and the call is annual - published spring flyers exist for consecutive years (2023, 2025, 2026). Laureates are also reached through the universities' own channels (the M2 mathematics pages list the same €1,200 x 10-month grant and note support from PSL's housing office for CROUS residence lodging).$desc$, $req$Students of any nationality admitted to - or applying for - one of the listed PSL Master in Mathematics curricula are eligible, with selection by online application on academic-excellence criteria; the scholarship and admission application is made on the PSL MyCandidature platform during the spring call window. The €1,200 monthly allowance is paid for ten months in the first year and can be renewed for a second year subject to conditions and a fresh renewal application - M1 laureates must progress into an eligible M2 curriculum. Note the language caveat: programmes are taught in English except the M1 Pure Mathematics year. The official call flyer publishes no numeric GPA or IELTS threshold for the grant (admission requirements are set by each curriculum), so min_gpa/min_ielts are not recorded. Registration fees and other costs must be met from the allowance - the grant is a living-cost scholarship, not a tuition waiver.$req$, 'https://psl.eu/en/graduate-programs/mathematics-and-applications', 'https://static.psl.eu/sites/default/files/2026-02/MATHEMATICS_GRADUATE_PROGRAM-Spring_call_2026%20%28flyer%29maj%20feb2026.pdf', 'https://candidatures.dauphine.fr/mycandidature/front/', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 16) from the PSL Graduate Program in Mathematics and Applications' official "Master Degree Scholarships - Call for Applications 2026/2027" flyer (static.psl.eu, February 2026) fetched the same day (10-month allowance of €1,200 per month for a year, renewable for a second year subject to conditions and a renewal application; national and international students; online selection on academic-excellence criteria across the M1 Applied Mathematics - Advanced Mathematics, M1 Pure Mathematics, M2 MATH, M2 IASD-Mathematics and M2 MASEF curricula, with the MAPPA PSL-Padova double degree on the M1 Applied schedule; CEREMADE/DMA laboratories; teaching in English except M1 Pure Mathematics; application via PSL MyCandidature under "Graduate Program in Mathematics and Applications"; call 27 February - 25 May 2026, and 27 February - 11 May 2026 for M1 Applied/MAPPA). The 2025 and 2023 flyers corroborate the annual pattern; an older Dauphine Leistungskatalog form (EUR650 + housing contribution, 2022) has been superseded by the €1,200 x 10 terms in the current flyers and the M2 curriculum pages, which govern. Award stored as 1200 EUR/month/fixed. deadline_date is NULL with type 'not_published' because the 2026-2027 call closed on 25 May 2026; the late-February-to-May spring pattern is recorded in rounds plus expected_opening/deadline periods, with status 'upcoming'. This record documents, on its own programme-level terms, one of the constituent grants of the umbrella record 52 retired in cleanup pass 109. min_gpa/min_ielts NULL. university_id set to the existing Université PSL record (44) and a university_scholarships row added.$note$, 44, 1200, 'EUR', 'month', 'fixed', NULL, 'Allowance of €1,200/month for 10 months in the first year (€12,000), renewable for a second year subject to conditions and a renewal application', 'The allowance is a living-cost scholarship; registration fees remain payable by the student.', 'No IELTS figure is published for the grant; teaching is in English except for the M1 Pure Mathematics curriculum (admission language rules per curriculum).', $j$["Online application on the PSL MyCandidature platform ('Graduate Program in Mathematics and Applications') during the spring call", "Academic transcripts/diplomas evidencing excellence for admission to one of the listed mathematics curricula (M1 or M2)", "For second-year continuation: a renewal application and satisfaction of the programme's conditions (including progression into an eligible M2)"]$j$, 'February', 'May', $json$[{"intake": "2026-2027 (last published)", "opens": "2026-02-27", "deadline": "2026-05-25", "deadline_m1_applied_mappa": "2026-05-11", "status": "closed"}, {"pattern": "Annual spring call: opens late February and closes in May (11 May for M1 Applied Mathematics - Advanced Mathematics and MAPPA; 25 May for other curricula in the 2026 call) for September entry; expect the next round from late February 2027"}]$json$);

INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES
(3098, 'https://pginfo.ens.psl.eu/last/scholarship_grants_en.html', 'Scholarship grants for PSL Master''s programs - PSL Graduate Program in Computer Science (official)', 'pginfo.ens.psl.eu', 'scholarship', now(), true, true, now()),
(3099, 'https://dauphine.psl.eu/en/training/masters-degrees/finance/finance-masters-year-1/excellence-scholarship', 'Excellence Scholarship, Finance: Master''s Year 1 - Dauphine-PSL (official)', 'dauphine.psl.eu', 'scholarship', now(), true, true, now()),
(3097, 'https://static.psl.eu/sites/default/files/2026-02/MATHEMATICS_GRADUATE_PROGRAM-Spring_call_2026%20%28flyer%29maj%20feb2026.pdf', 'Master Degree Scholarships, Call for Applications 2026/2027 - PSL Graduate Program in Mathematics and Applications (official flyer)', 'static.psl.eu', 'scholarship', now(), true, true, now());

INSERT INTO scholarship_sources (scholarship_id, source_id) VALUES (961, 3098), (962, 3099), (963, 3097);

INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES
(695, 44, 961, 'PSL Graduate Program in Computer Science Excellence Grants', 'available', 'Merit scholarship (Graduate Program in Computer Science)', '€1,200/month for 10 months (€12,000 per academic year); registration fees payable out of the grant', false, true, 'Academic excellence + motivation letter', 'Open to all nationalities applying to the research-oriented PSL computer-science tracks (M1 I2D; M2 IASD initial training; M2 MODO; M2 MPRI for PSL M1 graduates). Apply with the master''s application on MyCandidature (MonMaster applicants file the dedicated MyCandidature excellence campaign). Annual spring call - last deadline 8 June 2026, jury in June. Cannot be combined with other funding except French embassy/institute joint programmes.', 'https://pginfo.ens.psl.eu/last/scholarship_grants_en.html', 'https://pginfo.ens.psl.eu/last/scholarship_grants_en.html', 'verified', now()),
(694, 44, 962, 'PSL Graduate Program in Finance Excellence Scholarships (Dauphine-PSL)', 'available', 'Merit scholarship (Graduate Program in Finance, Dauphine-PSL)', '€12,000/year (€6,000/semester) for outstanding students in the Research in Finance track, subject to programme funds; tuition not covered', false, true, 'Outstanding grades (top-of-programme prizes; no application)', 'French and international students enrolled in M1 Finance - Research in Finance or M2 Research in Finance - 104. Awarded automatically on academic merit (e.g. top M1 grades in the six fundamental courses; top students of the M2 104 and its PhD Qualifying Year - the latter commits to the Dauphine-PSL Finance PhD). M1 awards may extend into M2 with commission approval. No separate application.', 'https://dauphine.psl.eu/en/training/masters-degrees/finance/finance-masters-year-1/excellence-scholarship', 'https://dauphine.psl.eu/en/training/masters-degrees/finance/finance-masters-year-1/excellence-scholarship', 'verified', now()),
(693, 44, 963, 'PSL Graduate Program in Mathematics and Applications Excellence Scholarships', 'available', 'Merit scholarship (Graduate Program in Mathematics and Applications)', '€1,200/month for 10 months (€12,000 in year one), renewable for a second year subject to conditions and renewal application', false, true, 'Academic excellence (online application selection)', 'National and international students in the PSL mathematics curricula (M1 Applied Mathematics - Advanced Mathematics; M1 Pure Mathematics; M2 MATH; M2 IASD-Mathematics; M2 MASEF; MAPPA double degree with Padova). Annual spring call on MyCandidature - last round 27 February to 25 May 2026 (11 May for M1 Applied/MAPPA). Teaching in English except M1 Pure Mathematics. Registration fees payable from the allowance.', 'https://psl.eu/en/graduate-programs/mathematics-and-applications', 'https://static.psl.eu/sites/default/files/2026-02/MATHEMATICS_GRADUATE_PROGRAM-Spring_call_2026%20%28flyer%29maj%20feb2026.pdf', 'verified', now());

SELECT setval('scholarships_id_seq', GREATEST((SELECT MAX(id) FROM scholarships), 963), true);
SELECT setval('sources_id_seq', GREATEST((SELECT MAX(id) FROM sources), 3099), true);
SELECT setval('university_scholarships_id_seq', GREATEST((SELECT MAX(id) FROM university_scholarships), 695), true);
